# coding: utf-8
"""046 small private workspace for source-backed retrieval and application trials."""
import html,urllib.parse
from dossier_layout import CSS
JS=r'''
const qs=new URLSearchParams(location.search),pid=qs.get('project')||'2025-00';let token='';const $=s=>document.querySelector(s),el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};const list=id=>$(id).value.split(/\n/).map(x=>x.trim()).filter(Boolean);
async function api(path,body){const r=await fetch(path+'?project='+encodeURIComponent(pid),body?{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':token},body:JSON.stringify(body)}:{});const d=await r.json();if(!r.ok)throw Error(d.error||'处理失败');return d;}
const request=()=>({task_id:'trial-'+Date.now(),title:$('#title').value,scenario_type:'simulated',needs:list('#needs'),functions:list('#functions'),constraints:list('#constraints'),unknowns:list('#unknowns')});
function paragraph(parent,label,value){if(value==null)return;parent.append(el('strong',label),el('p',Array.isArray(value)?value.join('；'):String(value)));}
function card(title){const n=el('article','');n.className='result-card';n.append(el('h3',title));$('#results').append(n);return n;}
function show(d){$('#results').replaceChildren();$('#output').textContent=JSON.stringify(d,null,2);if(d.matches){for(const hit of d.matches){const n=hit.node,c=card(n.title);paragraph(c,'相关内容',n.value);paragraph(c,'为什么命中',hit.hits.map(x=>x.term));paragraph(c,'内容性质',n.nature==='source_statement'?'来源陈述':'AI解读或待核信息');paragraph(c,'适用前提',n.conditions);paragraph(c,'限制',n.limitations);}if(!d.matches.length)card('没有逐字命中的知识；可以调整短语，未命中不代表项目不相关。');return;}
const a=d.analysis;if(d.request){$('#title').value=d.request.title;for(const key of ['needs','functions','constraints','unknowns'])$('#'+key).value=(d.request[key]||[]).join('\n');$('#trial-input').open=false;document.querySelector('h1').textContent=d.request.title;}if(d.execution_mode){const c=card('本次执行方式');paragraph(c,'分析方式',d.execution_mode.analysis==='trusted_reasoner_callback'?'真实Agent分析 · 已通过输出契约检查':'规则检索与研究计划编排');}if(!a){card('暂时没有可读结果');return;}const def=card('1. 问题定义');paragraph(def,'研究问题',d.request.title);paragraph(def,'需求',d.request.needs);paragraph(def,'约束',d.request.constraints);paragraph(def,'仍需确认',d.request.unknowns);const func=card('2. 功能分析');for(const f of a.function_analysis){paragraph(func,f.function,f.next_step||f.status);}const contra=card('3. 矛盾分析');paragraph(contra,'当前判断',a.contradiction_analysis.status==='unknown'?'目标系统的因果关系尚未明确，不能直接认定技术矛盾。':'目标矛盾假设，仍需验证');paragraph(contra,'依据与待问问题',a.contradiction_analysis.questions||a.contradiction_analysis.reason);
for(const h of a.hypotheses){const c=card(h.title+' · 待验证假设');paragraph(c,'建议探索',h.proposal);paragraph(c,'必要前提',h.assumptions);paragraph(c,'不能直接照搬的情况',h.not_applicable);paragraph(c,'怎样验证',h.validation);const titles=h.knowledge_refs.map(k=>d.selected_knowledge.find(n=>n.key===k)?.title||k);paragraph(c,'借鉴依据',titles);}
const conclusion=card('研究结论与限制');paragraph(conclusion,'结论',a.conclusions.map(c=>c.text));paragraph(conclusion,'边界',a.limitations);}
(async()=>{try{token=(await(await fetch('/api/projects')).json()).token;const d=await api('/api/innovation/overview');$('#knowledge-summary').textContent=d.nodes+' 个知识节点 · '+d.edges+' 条显式关系。AI解释关系与来源事实分别标记。';if(qs.get('run')){const r=await fetch('/api/innovation/run?project='+encodeURIComponent(pid)+'&run='+encodeURIComponent(qs.get('run')));const run=await r.json();if(!r.ok)throw Error(run.error||'无法读取研究试验');show(run);$('#message').textContent='正在阅读已保存的独立应用试验，来源版本保留，尚未经企业验证。';}}catch(e){$('#message').textContent=e.message;}})();
$('#search').onclick=async()=>{try{$('#message').textContent='正在检索项目知识…';show(await api('/api/innovation/search',request()));$('#message').textContent='已返回逐字命中、上下文优先级与适用边界；命中不等于可直接迁移。';}catch(e){$('#message').textContent=e.message;}};
$('#create').onclick=async()=>{const b=$('#create');b.disabled=true;try{$('#message').textContent='正在生成独立应用试验…';const job=await api('/api/innovation/create',{request:request(),use_model:$('#use-model').checked});for(let i=0;i<150;i++){await new Promise(r=>setTimeout(r,1000));const jobs=await api('/api/jobs');const row=jobs.jobs.find(x=>x.id===job.id);if(!row)continue;if(row.status==='failed')throw Error(row.error||'生成失败');if(row.status==='completed'){const r=await fetch('/api/innovation/run?project='+encodeURIComponent(pid)+'&run='+encodeURIComponent(row.result.run_id));const d=await r.json();if(!r.ok)throw Error(d.error||'读取失败');show(d);history.replaceState(null,'','/innovation/?project='+encodeURIComponent(pid)+'&run='+encodeURIComponent(row.result.run_id));$('#message').textContent='应用试验已保存，执行方式见报告，尚未经企业验证。';return;}}throw Error('生成仍在处理，请在资料管理的任务进度中查看');}catch(e){$('#message').textContent=e.message;}finally{b.disabled=false;}};

'''
def render(pid,header,shared_css):
 q=urllib.parse.urlencode(dict(project=pid));h=html.escape
 fields=''.join('<label>'+label+'<textarea id="'+name+'" rows="3" placeholder="'+h(placeholder)+'"></textarea></label>'for name,label,placeholder in [('needs','希望解决的问题（一行一项）','例如：保持样品内部信息'),('functions','需要完成的功能','例如：取样'),('constraints','必须遵守的约束','例如：远程作业、资源受限；请逐行输入'),('unknowns','还不清楚的条件','例如：目标材料、载荷、允许误差')])
 return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>创新研究试验</title><style>'+CSS+shared_css+'main{max-width:1000px;margin:30px auto;padding:0 24px}.trial-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}label{display:grid;gap:8px;font-size:14px}input,textarea{font:inherit;border:1px solid var(--line);border-radius:12px;background:white;padding:12px;min-width:0;width:100%;color:var(--ink)}textarea{resize:vertical}#use-model{width:auto;padding:0;margin:0;flex:none}.model-choice{display:flex;align-items:center;gap:10px}#trial-input>summary{cursor:pointer;color:var(--accent);padding:16px 0}.trial-actions{display:flex;gap:16px;margin:24px 0;flex-wrap:wrap}.trial-actions button{padding:12px 18px;border:1px solid var(--line);border-radius:12px;background:white}.trial-actions button:last-child{background:var(--accent);color:white}.result-card{background:white;border:1px solid var(--line);border-radius:18px;padding:24px;margin:16px 0}.result-card p{font-size:14px;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;background:white;border:1px solid var(--line);border-radius:18px;padding:20px}#message{color:var(--muted)}@media(max-width:650px){.trial-grid{grid-template-columns:1fr}}</style></head><body>'+header+'<main id="workspace-content"><p class="eyebrow">项目知识 × 创新方法</p><h1>把项目知识用到一个新问题</h1><p>从当前项目检索可借鉴的机制，结合问题定义、功能分析和矛盾分析生成独立研究试验。当前默认是可解释检索与方法编排；不冒充实时通用大模型推理或已验证企业方案。</p><p id="knowledge-summary"></p><details id="trial-input" open><summary>定义研究需求 / 修改后再次试验</summary><label>试验名称<input id="title" value="新产品研究试验" maxlength="200"></label><div class="trial-grid">'+fields+'</div><p><label class="model-choice"><input id="use-model" type="checkbox"> 使用真实AI生成研究分析（最多一次模型调用；连接失败会保留失败，不以规则冒充AI）</label></p><div class="trial-actions"><button id="search">先检索项目知识</button><button id="create">生成独立应用试验</button><a href="/dossier/?'+q+'">返回项目档案</a></div></details><p id="message" role="status"></p><section id="results" aria-live="polite"></section><details><summary>开发数据与完整引用</summary><pre id="output">填写需求后开始。</pre></details></main><script>'+JS+'</script></body></html>'
